#!/bin/bash
# (2026-10-19) 7b 모델 순위 단계(서술): 공개 표본 세 세트를 README 판 환경으로 원 분석 코드(SASA 포함, 0408d7c) 그대로. AlphaFlow-MD 는 표 재현 판(readmeenv_out.pkl)을 쓴다.
until [ -f /content/AFENV_READY ] && [ -f /content/ATLAS_READY ]; do sleep 60; done
